const express = require("express");
const paymentRoutes = require("./routes/payments");
const app = express();
app.use(express.json());
app.use("/payments", paymentRoutes);
app.listen(3000);

const express = require("express");
const router = express.Router();
const { processPayment } = require("../services/paymentService");

router.post("/", async (req, res) => {
  const result = await processPayment(req.body);
  res.json(result);
});
module.exports = router;

const transactions = [];

async function processPayment(data) {
  const { amount, idempotencyKey } = data;

  // BUG: No check if idempotencyKey already exists in transactions
  const transaction = { id: Date.now(), amount, idempotencyKey, status: "SUCCESS" };
  transactions.push(transaction);

  return transaction;
}

module.exports = { processPayment, transactions };

const { processPayment, transactions } = require("../src/services/paymentService");

test("Retry should not duplicate charge", async () => {
  transactions.length = 0;
  await processPayment({ amount: 100, idempotencyKey: "abc" });
  await processPayment({ amount: 100, idempotencyKey: "abc" });

  if (transactions.length > 1) {
    throw new Error("Duplicate charge created!");
  }
});
